import React from "react";

export default function Assignments() {

const assignments = [

{

id:1,

title:"Java Mini Project",

course:"Java Full Stack",

due:"20 June 2026",

marks:"100",

status:"Pending"

},

{

id:2,

title:"React Dashboard",

course:"React JS",

due:"25 June 2026",

marks:"50",

status:"Submitted"

},

{

id:3,

title:"Python Quiz",

course:"Python",

due:"28 June 2026",

marks:"25",

status:"Pending"

},

{

id:4,

title:"SQL Database Design",

course:"DBMS",

due:"30 June 2026",

marks:"75",

status:"Completed"

}

];

return(

<div

style={{

minHeight:"100vh",

background:"#f3f4f6",

padding:"40px"

}}

>

<h1

style={{

textAlign:"center",

fontSize:"40px",

color:"#1e293b",

marginBottom:"10px"

}}

>

📝 Assignments

</h1>

<p

style={{

textAlign:"center",

color:"gray",

marginBottom:"40px"

}}

>

Track and Submit Your Assignments

</p>


<div

style={{

display:"grid",

gridTemplateColumns:

"repeat(auto-fit,minmax(320px,1fr))",

gap:"30px"

}}

>

{

assignments.map((item)=>(

<div

key={item.id}

style={{

background:"white",

padding:"25px",

borderRadius:"20px",

boxShadow:

"0 10px 25px rgba(0,0,0,0.1)"

}}

>

<h2

style={{

color:"#2563eb",

marginBottom:"20px"

}}

>

{item.title}

</h2>


<p>

📚

<b>

Course :

</b>

{item.course}

</p>


<p>

📅

<b>

Due Date :

</b>

{item.due}

</p>


<p>

🏆

<b>

Marks :

</b>

{item.marks}

</p>


<p>

📌

<b>

Status :

</b>

<span

style={{

fontWeight:"bold",

color:

item.status==="Submitted"

?

"green"

:

item.status==="Completed"

?

"#2563eb"

:

"orange"

}}

>

{item.status}

</span>

</p>


<button

style={{

width:"100%",

padding:"12px",

marginTop:"20px",

background:"#2563eb",

color:"white",

border:"none",

borderRadius:"10px",

cursor:"pointer",

fontSize:"16px"

}}

onClick={()=>

alert(

"Assignment Opened : "

+

item.title

)

}

>

View Assignment

</button>

</div>

))

}

</div>

</div>

)

}
